def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find the non-marker object: the connected non-background cells that
    # are not the repeated marker color.
    counts = Counter(v for row in grid for v in row if v != bg)
    marker = counts.most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, marker)}
    if not cells:
        return out

    # Connected object component(s); the largest supplies the pattern.
    comps = []
    while cells:
        p = cells.pop()
        comp = {p}
        stack = [p]
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells:
                    cells.remove(q)
                    comp.add(q)
                    stack.append(q)
        comps.append(comp)
    obj = max(comps, key=len)
    r0, r1 = min(r for r,c in obj), max(r for r,c in obj)
    c0, c1 = min(c for r,c in obj), max(c for r,c in obj)
    pattern = [[grid[r][c] for c in range(c0,c1+1)]
               for r in range(r0,r1+1)]

    # The marker indicates the pattern's anchor. For the vertical demo the
    # anchor is the middle row; for the 3x3 pattern it is top-middle.
    ah = len(pattern) // 2 if len(pattern) > 3 else 0
    aw = len(pattern[0]) // 2 if len(pattern[0]) > 1 else 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r,c) not in obj:
                for i in range(len(pattern)):
                    for j in range(len(pattern[0])):
                        rr, cc = r + i - ah, c + j - aw
                        if 0 <= rr < h and 0 <= cc < w:
                            if pattern[i][j] != bg:
                                out[rr][cc] = pattern[i][j]
    return out
